    },
    {
      "id": "FAM:SF-TMP-021",
      "status_as_recorded": "inconclusive",
      "finding": "In a pilot test of behavior change when the defense enters the penalty, the penalty contrast was not distinct from 2-to-3 and 4-to-5+ placebo contrasts. Standard errors were not printed."
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-TMP-009",
      "what_failed": "Claiming a PULL_UP-specific decline with exposure was due to defensive adaptation without controlling for lineup fixed effects or using same-shooter placebos.",
      "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw) due to confounding (shooter-level confound)."
    },
    {
      "id": "FAM:SF-TMP-012",
      "what_failed": "Assuming a published suppression excess was a true effect beyond null models.",
      "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw) due to mechanical effects under selection rules and potential drift."
    },
    {
      "id": "FAM:SF09",
      "what_failed": "Assuming additive stacking of opponent effects and drawing conclusions from per-player stacked estimates.",
      "why": "LIM:small_sample, LIM:implementation_bug, leading to inconclusive results and unexpected gradients."
