    "p_testable": 0.6,
    "blocking_constraints": [
      {
        "code": "CONFOUNDING",
        "text": "Lineup changes are not random and are often driven by game state, opponent, or player performance, which also influence shot mix. Isolating the 'lineup effect itself' requires careful control of these confounders."
